//! Snapshot and restore, and the JIT fault latch beside them.

use crate::heap::*;

impl Heap {
    /// Checkpoint: serialize the heap's live DATA (objects, arrays, maps, side
    /// tables, field-name intern, GC liveness) to a byte buffer. Runtime-only
    /// state — native descriptors + `jit_ctx` (raw pointers) — is omitted and
    /// regenerated by `restore`. This is the generic, jar-agnostic foundation of
    /// boot snapshot/restore (skip re-running deterministic init on a later run).
    pub fn snapshot(&self) -> Vec<u8> {
        let arrays = SnapshotArrays(self);
        bincode::serialize(&(
            &self.objects,
            &arrays,
            &self.field_box,
            &self.array_box,
            &self.maps,
            &self.field_names,
            self.bytes.load(std::sync::atomic::Ordering::Relaxed) as u64,
            &self.obj_alive,
            &self.arr_alive,
            &self.map_alive,
            &self.free_obj,
            &self.free_arr,
            &self.free_map,
        ))
        .unwrap_or_default()
    }

    /// Reconstruct a heap from `snapshot` bytes: deserialize the data, re-intern
    /// class names so objects share one `Arc<str>` per name, rebuild the
    /// field-name id map, and regenerate the native field/array descriptors.
    /// `None` on a malformed buffer.
    pub fn restore(bytes: &[u8]) -> Option<Heap> {
        let t_start = std::time::Instant::now();
        type Snap = (
            Vec<Object>,
            Vec<SnapshotArray>,
            Vec<Value>,
            Vec<Value>,
            Vec<MapObj>,
            Vec<Box<str>>,
            u64,
            Vec<bool>,
            Vec<bool>,
            Vec<bool>,
            Vec<u32>,
            Vec<u32>,
            Vec<u32>,
        );
        let (
            objects,
            arrays,
            field_box,
            array_box,
            maps,
            field_names,
            bytes,
            obj_alive,
            arr_alive,
            map_alive,
            free_obj,
            free_arr,
            free_map,
        ): Snap = bincode::deserialize(bytes).ok()?;
        let prof = std::env::var("RAVA_RESTORE_PROF").is_ok();
        let (no, na) = (objects.len(), arrays.len());
        let t_deser = t_start.elapsed();
        let t1 = std::time::Instant::now();
        let mut h = Heap::default();
        h.field_ids = std::sync::RwLock::new(
            field_names
                .iter()
                .enumerate()
                .map(|(i, n)| (n.clone(), i as u32))
                .collect(),
        );
        h.field_names = std::sync::RwLock::new(field_names);
        for (index, mut o) in objects.into_iter().enumerate() {
            if null_object_slots_enabled()
                && !obj_alive.get(index).copied().unwrap_or(false)
            {
                h.objects.write().unwrap_or_else(|e| e.into_inner()).push(ObjectSlot(None));
                continue;
            }
            let name: Box<str> = o.class.as_ref().into();
            let rc = h.intern(&name);
            o.class = rc;
            h.objects.write().unwrap_or_else(|e| e.into_inner()).push(ObjectSlot::live(o));
        }
        for (index, array) in arrays.into_iter().enumerate() {
            let element_id = if arr_alive.get(index).copied().unwrap_or(false) {
                h.intern_array_element(array.element.as_ref())
            } else {
                DEAD_ARRAY_ELEMENT_ID
            };
            let data = array.data;
            h.array_descs.write().unwrap_or_else(|e| e.into_inner()).push(ArrayDesc {
                data: data.data_ptr(),
                len: data.len() as u32,
                element_id,
            });
            h.arrays.write().unwrap_or_else(|e| e.into_inner()).push(ArrayObj { data });
        }
        h.field_box = std::sync::RwLock::new(field_box);
        h.array_box = std::sync::RwLock::new(array_box);
        h.maps = maps;
        h.bytes = std::sync::atomic::AtomicUsize::new(bytes as usize);
        h.obj_alive = std::sync::Mutex::new(obj_alive);
        h.arr_alive = std::sync::RwLock::new(arr_alive);
        h.map_alive = map_alive;
        h.free_obj = std::sync::Mutex::new(free_obj);
        h.free_arr = std::sync::Mutex::new(free_arr);
        h.free_map = free_map;
        let t_rebuild = t1.elapsed();
        let t2 = std::time::Instant::now();
        for i in 0..h.arrays.read().unwrap_or_else(|e| e.into_inner()).len() as u32 {
            h.sync_array_desc(i);
        }
        // Stage 2c: the length and the per-slot probe are taken in STATEMENTS of their
        // own, so each read guard is released before `sync_obj_desc` takes `&mut h`.
        // A guard in the `for`-header would live across the whole loop body.
        let n_objs = h.objects.read().unwrap_or_else(|e| e.into_inner()).len() as u32;
        for i in 0..n_objs {
            let live = h.objects.read().unwrap_or_else(|e| e.into_inner())[i as usize].get().is_some();
            if live {
                h.sync_obj_desc(i);
            } else {
                h.obj_descs.write().unwrap_or_else(|e| e.into_inner()).push(ObjDesc::empty());
            }
        }
        h.jit_ctx.obj_desc_base = h.obj_descs.read().unwrap_or_else(|e| e.into_inner()).as_ptr() as usize;
        h.jit_ctx.objects_base = h.objects.read().unwrap_or_else(|e| e.into_inner()).as_ptr() as usize;
        // GAP-P04: salt counters are not on the wire — rebuild them from the salted
        // index keys so post-restore mints can never alias a live salt.
        for m in h.maps.iter_mut() {
            Self::rebuild_salt_counters(m);
        }
        if prof {
            eprintln!(
                "[RESTORE-PROF] {no} objs, {na} arrs | deserialize {:?} | rebuild/re-intern {:?} | descriptors {:?}",
                t_deser, t_rebuild, t2.elapsed()
            );
        }
        Some(h)
    }

    /// Clear the native-access fault latch (called at each compiled-call entry).
    pub(crate) fn clear_jit_fault(&mut self) {
        set_active_jit_fault(&mut self.jit_ctx, 0);
    }

    /// Latch a native-access fault so later native stores in the same compiled
    /// method short-circuit (the method is unwinding to a pending exception).
    pub(crate) fn set_jit_fault(&mut self) {
        set_active_jit_fault(&mut self.jit_ctx, 1);
    }

    /// Live channel objects that were bound listeners (`$bound==1`), with their
    /// `$port`/`$host` — so a restored VM can re-open the real OS sockets that
    /// weren't (couldn't be) serialized. O(objects), called once at restore.
    pub fn bound_listeners(&self) -> Vec<(u32, i32, String)> {
        let mut out = Vec::new();
        for h in 0..self.objects.read().unwrap_or_else(|e| e.into_inner()).len() {
            if !self.obj_alive.lock().unwrap_or_else(|e| e.into_inner()).get(h).copied().unwrap_or(false) {
                continue;
            }
            if self.get_field(h as u32, "$bound").as_int() == Some(1) {
                let port = self.get_field(h as u32, "$port").as_int().unwrap_or(0);
                let host = match self.get_field(h as u32, "$host") {
                    Value::Str(s) => s.to_string(),
                    _ => "0.0.0.0".to_string(),
                };
                out.push((h as u32, port, host));
            }
        }
        out
    }
}
